#!/usr/bin/env node
// Đồng bộ interface platform ops chuẩn của facade (Thùng rác, clone tenant, dọn/khôi phục học sinh — ADR-0028/0029/0032/0074)
// từ thư viện `specs/openapi/modules/common/internal-common.v1.yaml` (NGUỒN SỰ THẬT) vào từng
// `specs/openapi/modules/<module>.internal.v1.yaml`, giữa hai dấu mốc:
//   # BEGIN platform-ops (generated by scripts/openapi/sync-platform-ops.mjs — do not edit)
//   # END platform-ops
// Path item được chép inline (Spectral không chấp nhận path-item $ref ra file ngoài); các $ref bên trong
// được đổi sang tham chiếu tới file thư viện để chỉ có một định nghĩa schema/response/parameter.
// Khối thứ hai `ops-reconcile` (F134): `x-ops-reconcile-paths` của thư viện (listOutboxEventIds, listProcessedEventIds)
// chép vào cả 5 module có database (gồm identity) giữa `# BEGIN ops-reconcile …` / `# END ops-reconcile`; file chưa có
// dấu mốc được thêm khối ngay trước `components:`.
//
// Chạy:  npm ci --prefix scripts && node scripts/openapi/sync-platform-ops.mjs [--check]
import { createRequire } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const yaml = require('js-yaml');

const here = path.dirname(fileURLToPath(import.meta.url));
const dir = path.resolve(here, '..', '..', 'specs/openapi/modules');
const LIB = 'common/internal-common.v1.yaml';
const TARGETS = ['learning', 'game', 'competition', 'chat'];
const BEGIN = '  # BEGIN platform-ops (generated by scripts/openapi/sync-platform-ops.mjs — do not edit)';
const END = '  # END platform-ops';
const checkOnly = process.argv.includes('--check');

const lib = yaml.load(fs.readFileSync(path.join(dir, LIB), 'utf8'));
const rewrite = (n) => {
  if (Array.isArray(n)) return n.map(rewrite);
  if (n && typeof n === 'object') {
    const o = {};
    for (const [k, v] of Object.entries(n)) o[k] = k === '$ref' && typeof v === 'string' && v.startsWith('#/') ? `${LIB}${v}` : rewrite(v);
    return o;
  }
  return n;
};
const indent = (paths) => yaml.dump(rewrite(paths), { lineWidth: -1, noRefs: true, sortKeys: false })
  .trimEnd().split('\n').map((l) => `  ${l}`).join('\n');
const BLOCKS = [
  { name: 'platform-ops', begin: BEGIN, end: END, paths: lib.paths, targets: TARGETS, required: true },
  {
    name: 'ops-reconcile',
    begin: '  # BEGIN ops-reconcile (generated by scripts/openapi/sync-platform-ops.mjs — do not edit)',
    end: '  # END ops-reconcile',
    paths: lib['x-ops-reconcile-paths'],
    targets: ['identity', ...TARGETS],
    required: false,
  },
];

let changed = 0;
for (const s of ['identity', ...TARGETS]) {
  const f = path.join(dir, `${s}.internal.v1.yaml`);
  const src = fs.readFileSync(f, 'utf8');
  let next = src;
  for (const blk of BLOCKS) {
    if (!blk.targets.includes(s)) continue;
    const block = `${blk.begin}\n${indent(blk.paths)}\n${blk.end}`;
    const a = next.indexOf(blk.begin), b = next.indexOf(blk.end);
    if (a >= 0 && b >= 0) {
      next = next.slice(0, a) + block + next.slice(b + blk.end.length);
    } else if (blk.required) {
      throw new Error(`Thiếu dấu mốc ${blk.name} trong ${f}`);
    } else {
      const c = next.indexOf('\ncomponents:');
      if (c < 0) throw new Error(`Thiếu components: trong ${f}`);
      next = `${next.slice(0, c).trimEnd()}\n\n${block}\n${next.slice(c)}`;
    }
  }
  if (next !== src) { changed++; if (!checkOnly) fs.writeFileSync(f, next); }
  console.log(`${s}.internal.v1.yaml: ${next !== src ? (checkOnly ? 'KHÁC' : 'đã cập nhật') : 'không đổi'}`);
}
if (checkOnly && changed) { console.error('platform-ops/ops-reconcile chưa đồng bộ — chạy lại sync-platform-ops.mjs'); process.exit(1); }
